        for y in sorted(by_row):
            items = by_row[y]
            print(f"  行{y}: {len(items)}格", end=" ")
            for x, old, new in items[:10]:
                print(f"({x}:{old}→{new})", end=" ")
            if len(items) > 10:
                print(f"...共{len(items)}格", end="")
            print()
        break
